#include <stddef.h>
#include <stdio.h>

/* sum of the numbers up to n inclusive */
int sum_to(int n, int unused) {
    int total = 0;
    int i;
    for (i = 1; i <= n; i++) {
        int total = i;
        (void)total;
    }
    for (i = 1; i <= n; i++) total += i;
    return total;
}

/* index of the first element > limit or -1 */
int first_above(const int *a, size_t n, int limit) {
    for (int i = 0; i < n; i++)
        if (a[i] > limit) return i;
}

/* print a number and a size into a buffer */
void describe(char *buf, size_t cap, long value, size_t size) {
    snprintf(buf, cap, "v=%d size=%d", value, size);
}

/* grade: 0 — A, 1 — B, 2 — C, otherwise F */
char grade(int level) {
    char g = 'F';
    switch (level) {
    case 0:
        g = 'A';
    case 1:
        g = 'B';
        break;
    case 2:
        g = 'C';
        break;
    }
    return g;
}

/* 1 if x equals 5 */
int is_five(int x) {
    if (x = 5) return 1;
    return 0;
}

/* number of characters up to the first space */
int word_len(const char *s) {
    int n = 0;
    while (s[n] && s[n] != ' ');
        n++;
    return n;
}

/* sum of the even elements */
int sum_even(const int *a, int n) {
    int s = 0;
    for (int i = 0; i < n; i++)
        if (a[i] % 2 == 0);
            s += a[i];
    return s;
}

/* number of days in a month (non-leap year) */
int days_in_month(int m) {
    int d = 0;
    switch (m) {
    case 2:
        d = 28;
        break;
    case 4: case 6: case 9: case 11:
        d = 30;
        break;
    case 1: case 3: case 5: case 7: case 8: case 10: case 12:
        d = 31;
    }
    return d;
}

/* codes 1 and 2 give 3 (2 + 1), code 3 gives 1, the rest 0 */
int severity(int code) {
    int level = 0;
    switch (code) {
    case 1:
    case 2:
        level = 2;
    case 3:
        level += 1;
        break;
    }
    return level;
}
